import 'package:flutter/material.dart';

import '../design_tokens.dart';

/// The three button variants named in prototype-extract.md §6's component
/// table: primary (filled), secondary (outline), text (ghost).
enum AppButtonVariant { primary, secondaryOutline, textGhost }

/// Shared button primitive consumed by every feature's `presentation/`
/// (Story 1.3 login/signup, Story 1.5 overlay, Story 1.6 nav shell).
///
/// Disabled state is identical across all three variants, per the
/// project-wide rule: `colorBorder` background + `colorTextSecondary`
/// text, never a dimmed-opacity look.
class AppButton extends StatelessWidget {
  const AppButton({
    super.key,
    required this.label,
    required this.onPressed,
    this.variant = AppButtonVariant.primary,
    this.textColor,
  });

  /// Button label. Rendered with no `maxLines`/`overflow` clamp so it
  /// wraps rather than clips or truncates under Dynamic Type.
  final String label;

  /// Null disables the button and switches it to the disabled visual
  /// state (see class doc).
  final VoidCallback? onPressed;

  final AppButtonVariant variant;

  /// Only consulted for [AppButtonVariant.textGhost]: the component table
  /// allows ghost buttons to use either `colorPrimary` or
  /// `colorTextSecondary` depending on context (e.g. "Fechar"/"Limpar").
  /// Defaults to `colorPrimary`.
  final Color? textColor;

  @override
  Widget build(BuildContext context) {
    final Widget child = Text(
      label,
      textAlign: TextAlign.center,
      style: DesignTokens.textLabelMd,
    );

    final ButtonStyle baseStyle = ButtonStyle(
      padding: const WidgetStatePropertyAll(DesignTokens.buttonPadding),
      shape: const WidgetStatePropertyAll(
        RoundedRectangleBorder(
          borderRadius: BorderRadius.all(
            Radius.circular(DesignTokens.radiusSm),
          ),
        ),
      ),
      elevation: const WidgetStatePropertyAll(0),
    );

    switch (variant) {
      case AppButtonVariant.primary:
        return ElevatedButton(
          onPressed: onPressed,
          style: baseStyle.copyWith(
            backgroundColor: WidgetStateProperty.resolveWith((states) {
              if (states.contains(WidgetState.disabled)) {
                return DesignTokens.colorBorder;
              }
              return DesignTokens.colorPrimary;
            }),
            foregroundColor: WidgetStateProperty.resolveWith((states) {
              if (states.contains(WidgetState.disabled)) {
                return DesignTokens.colorTextSecondary;
              }
              return DesignTokens.colorOnPrimary;
            }),
            overlayColor: WidgetStateProperty.resolveWith((states) {
              if (states.contains(WidgetState.pressed)) {
                return DesignTokens.colorPrimaryPressed;
              }
              return Colors.transparent;
            }),
          ),
          child: child,
        );

      case AppButtonVariant.secondaryOutline:
        return OutlinedButton(
          onPressed: onPressed,
          style: baseStyle.copyWith(
            backgroundColor: WidgetStateProperty.resolveWith((states) {
              if (states.contains(WidgetState.disabled)) {
                return DesignTokens.colorBorder;
              }
              return Colors.transparent;
            }),
            foregroundColor: WidgetStateProperty.resolveWith((states) {
              if (states.contains(WidgetState.disabled)) {
                return DesignTokens.colorTextSecondary;
              }
              return DesignTokens.colorPrimary;
            }),
            side: WidgetStateProperty.resolveWith((states) {
              if (states.contains(WidgetState.disabled)) {
                return const BorderSide(
                  color: DesignTokens.colorBorder,
                  width: DesignTokens.borderWidthDefault,
                );
              }
              return const BorderSide(
                color: DesignTokens.colorPrimary,
                width: DesignTokens.borderWidthDefault,
              );
            }),
          ),
          child: child,
        );

      case AppButtonVariant.textGhost:
        return TextButton(
          onPressed: onPressed,
          style: baseStyle.copyWith(
            backgroundColor: WidgetStateProperty.resolveWith((states) {
              if (states.contains(WidgetState.disabled)) {
                return DesignTokens.colorBorder;
              }
              return Colors.transparent;
            }),
            foregroundColor: WidgetStateProperty.resolveWith((states) {
              if (states.contains(WidgetState.disabled)) {
                return DesignTokens.colorTextSecondary;
              }
              return textColor ?? DesignTokens.colorPrimary;
            }),
          ),
          child: child,
        );
    }
  }
}

// The constructor keeps public named params (`dio`, `urlBuilder`) distinct
// from the private fields they initialize, so an initializing formal
// (which would force the external name to match) isn't a clean fit here.
// ignore_for_file: prefer_initializing_formals
import 'dart:convert';

import 'package:dio/dio.dart';
import 'package:flutter/foundation.dart';
import 'package:fpdart/fpdart.dart';

import '../failure/failure.dart';
import '../session/session_expiry_notifier.dart';
import 'dio_error_code.dart';
import 'header_interceptor.dart';
import 'url_builder.dart';

/// AD-2/AD-5 — the one network façade every repository's data source calls
/// through. Builds the real URL via `UrlBuilder`, sends the request through
/// `dio` (header + retry interceptors already attached in DI), and maps
/// every outcome — success or failure — to `Either<Failure, T>`; no
/// dio/native exception ever escapes unmapped (RNF09).
///
/// Story 1.5: also the one detection point for a mid-session `AUTH_EXPIRED`
/// — signals [SessionExpiryNotifier] when one is seen outside
/// `HeaderInterceptor.anonKeyOnlyFunctions`, so the boot-time `auth-refresh`
/// call (Story 1.4's `restoreSession()`) never triggers it.
///
/// Tests mock this interface directly (per the architecture spine's testing
/// convention), not a fake transport layer underneath it.
class ApiClient {
  ApiClient({
    required Dio dio,
    required UrlBuilder urlBuilder,
    required SessionExpiryNotifier sessionExpiryNotifier,
  }) : _dio = dio,
       _urlBuilder = urlBuilder,
       _sessionExpiryNotifier = sessionExpiryNotifier;

  final Dio _dio;
  final UrlBuilder _urlBuilder;
  final SessionExpiryNotifier _sessionExpiryNotifier;

  Future<Either<Failure, Map<String, dynamic>>> get(
    String function, {
    List<String> pathParams = const [],
    Map<String, dynamic>? queryParameters,
  }) => _send(
    () => _dio.get<Map<String, dynamic>>(
      _urlBuilder.build(function, pathParams),
      queryParameters: queryParameters,
    ),
  );

  Future<Either<Failure, Map<String, dynamic>>> post(
    String function, {
    List<String> pathParams = const [],
    Object? data,
  }) => _send(
    () => _dio.post<Map<String, dynamic>>(
      _urlBuilder.build(function, pathParams),
      data: data,
    ),
  );

  Future<Either<Failure, Map<String, dynamic>>> patch(
    String function, {
    List<String> pathParams = const [],
    Object? data,
  }) => _send(
    () => _dio.patch<Map<String, dynamic>>(
      _urlBuilder.build(function, pathParams),
      data: data,
    ),
  );

  Future<Either<Failure, Map<String, dynamic>>> delete(
    String function, {
    List<String> pathParams = const [],
    Object? data,
  }) => _send(
    () => _dio.delete<Map<String, dynamic>>(
      _urlBuilder.build(function, pathParams),
      data: data,
    ),
  );

  /// spec-7-2 — `export-download-get`'s own shape: the real payload is the
  /// `302` response's `Location` header (a signed Storage URL), never a
  /// JSON body. `followRedirects: false` stops dio from auto-following
  /// into that signed-storage host itself (Boundaries); the permissive
  /// `validateStatus` (anything below 400) keeps dio from throwing on the
  /// `302` the way its own default validator (`>= 200 && < 300`) would.
  /// `responseType` is deliberately left at its default — an *error*
  /// response (>= 400) still decodes as JSON, so `_mapDioException`/
  /// `dioErrorCodeOf` keep mapping it exactly as they do for every other
  /// call on this façade, unchanged.
  ///
  /// A `302` with no `Location` header (shouldn't happen — the contract's
  /// own response is declared as exactly this) maps to
  /// [Failure.malformedResponse] rather than returning an empty/null URL
  /// (RNF09, I/O matrix: "Missing Location").
  Future<Either<Failure, String>> getRedirectLocation(
    String function, {
    List<String> pathParams = const [],
    Map<String, dynamic>? queryParameters,
  }) async {
    try {
      final response = await _dio.get<dynamic>(
        _urlBuilder.build(function, pathParams),
        queryParameters: queryParameters,
        options: Options(
          followRedirects: false,
          validateStatus: (status) => status != null && status < 400,
        ),
      );
      final location = response.headers.value('location');
      if (location == null) {
        return left(
          const Failure.malformedResponse(message: 'Missing Location header'),
        );
      }
      return right(location);
    } on DioException catch (e) {
      return left(_mapDioException(e));
    } catch (e) {
      return left(Failure.malformedResponse(message: e.toString()));
    }
  }

  /// spec-6-1 — streaming companion to [post]: sent with
  /// `ResponseType.stream` so the SSE response body never gets buffered
  /// into a single in-memory JSON blob the way [post]'s own
  /// `Dio.post<Map<String, dynamic>>` would. Each emitted `Right` is one
  /// raw, UTF-8-decoded chunk straight off the wire — SSE `event:`/`data:`
