21	/// own fake adapter — only the transport boundary is faked.
22	class _FakeHttpClientAdapter implements HttpClientAdapter {
23	  final List<RequestOptions> requests = [];
24	  final List<
25	    ({int statusCode, Map<String, dynamic>? body, Map<String, String>? headers})
26	  >
