33	  /// spec-7-2 review patch (item 8) — queues a `302` with no JSON body,
34	  /// just a `Location` header, mirroring `export-download-get`'s own real
35	  /// shape (`openapi.yaml`: "302: Redirect to a signed Storage URL").
36	  void queueRedirectResponse(String location) {
37	    _queue.add((statusCode: 302, body: null, headers: {'location': location}));
38	  }
