40	  @override
41	  Future<ResponseBody> fetch(
42	    RequestOptions options,
43	    Stream<Uint8List>? requestStream,
44	    Future<void>? cancelFuture,
45	  ) async {
46	    requests.add(options);
47	    if (_queue.isEmpty) {
48	      throw StateError(
49	        'No queued response for ${options.method} ${options.path}',
50	      );
51	    }
52	    final next = _queue.removeAt(0);
53	    final body = next.body;
54	    return ResponseBody.fromString(
55	      body != null ? jsonEncode(body) : '',
56	      next.statusCode,
57	      headers: {
58	        if (body != null) Headers.contentTypeHeader: [Headers.jsonContentType],
59	        ...next.headers?.map((key, value) => MapEntry(key, [value])) ?? {},
60	      },
61	    );
62	  }
